file.content:
.big-seat {
    position: absolute;
    width: 80px;
    height: 90px;
    background: rgba(255,255,255,0.1);
    border-radius: 10px;
    border: 2px solid rgba(255,255,255,0.3);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s;
}

.big-seat:hover {
    background: rgba(255,255,255,0.2);
    border-color: #FFD700;
    transform: scale(1.05);
}

.big-seat.occupied {
    background: rgba(76, 175, 80, 0.3);
    border-color: #4CAF50;
}

.big-seat.occupied:hover {
    transform: none;
    cursor: default;
}

.big-seat.playing {
    background: rgba(33, 150, 243, 0.3);
    border-color: #2196F3;
}

.seat-direction {
    font-size: 14px;
    font-weight: bold;
    color: #FFD700;
    margin-bottom: 5px;
}

.seat-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(255,255,255,0.2);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: bold;
    color: #fff;
    border: 2px solid rgba(255,255,255,0.3);
    margin-bottom: 5px;
}

.big-seat.occupied .seat-avatar {
    background: linear-gradient(135deg, #4CAF50, #2E7D32);
    border-color: #81C784;
    font-size: 16px;
}

.seat-name {
    font-size: 12px;
    color: #fff;
    max-width: 70px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* 座位位置 - 逆时针：南(1)西(2)北(3)东(4) */
.big-seat-south { bottom: -45px; left: 50%; transform: translateX(-50%); }
.big-seat-west { left: -45px; top: 50%; transform: translateY(-50%); }
.big-seat-north { top: -45px; left: 50%; transform: translateX(-50%); }
.big-seat-east { right: -45px; top: 50%; transform: translateY(-50%); }

.big-seat-south:hover { transform: translateX(-50%) scale(1.05); }
.big-seat-west:hover { transform: translateY(-50%) scale(1.05); }
.big-seat-north:hover { transform: translateX(-50%) scale(1.05); }
.big-seat-east:hover { transform: translateY(-50%) scale(1.05); }

.table-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 5px;
}

.table-id {
    color: #FFD700;
    font-size: 14px;
    font-weight: bold;
}

.table-mode-badge {
    font-size: 11px;
    padding: 2px 6px;
    border-radius: 4px;
    background: rgba(255, 215, 0, 0.2);
    color: #FFD700;
}

.table-footer {
    text-align: center;
    font-size: 12px;
    color: #ccc;
    margin-top: 10px;
}

.table-footer.full {
    color: #ff6b6b;
}

.table-footer.playing {
    color: #4dabf7;
}

.deck-info {
    text-align: center;
    font-size: 11px;
    color: #90ee90;
    margin-top: 5px;
    padding: 3px 8px;
    background: rgba(0, 0, 0, 0.3);
    border-radius: 4px;
}

/* 创建新桌卡片样式 */
.create-table-card {
    background: linear-gradient(135deg, rgba(76, 175, 80, 0.3), rgba(46, 125, 50, 0.3));
    border: 2px dashed #4CAF50;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 200px;
}

.create-table-card .plus {
    font-size: 48px;
    color: #4CAF50;
    line-height: 1;
}

.create-table-card .text {
    color: #4CAF50;
    font-size: 16px;
    margin-top: 10px;
}

.create-table-card:hover {
    background: linear-gradient(135deg, rgba(76, 175, 80, 0.5), rgba(46, 125, 50, 0.5));
}

/* 游戏界面样式 */
.game-container {
    display: none;
    width: 100vw;
    height: 100vh;
    position: relative;
}

.game-table {
    width: 100%;
    height: 100%;
    position: relative;
    background: radial-gradient(ellipse at center, #2d5a3d 0%, #1a472a 100%);
}

/* 玩家区域 */
.player-area {
    position: absolute;
    display: flex;
    flex-direction: column;
    align-items: center;
}

.player-area.bottom {
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    width: 80%;
}

.player-area.top {
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
}

.player-area.left {
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
}

.player-area.right {

