/* 中央信息区 - 简化版 */
.center-info {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    background: rgba(0,0,0,0.5);
    padding: 10px;
    border-radius: 10px;
    min-width: 120px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
}

/* 方位标记 */
.direction-marks {
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
}

.direction {
    position: absolute;
    font-size: 16px;
    font-weight: bold;
    color: #FFD700;
}

.direction.north { top: 5px; left: 50%; transform: translateX(-50%); }
.direction.south { bottom: 5px; left: 50%; transform: translateX(-50%); }
.direction.east { right: 15px; top: 50%; transform: translateY(-50%); }
.direction.west { left: 15px; top: 50%; transform: translateY(-50%); }

/* 庄家标记 */
.dealer-mark {
    display: none;
    margin-left: 4px;
    font-size: 12px;
    color: #FF6B6B;
    background: #FFF;
    border-radius: 3px;
    padding: 1px 4px;
    font-weight: bold;
}
.dealer-mark.show {
    display: inline;
}

/* 中央内容 */
.center-content {
    z-index: 1;
}

.beijing-time {
    font-size: 18px;
    font-weight: bold;
    color: #fff;
    text-shadow: 0 0 10px #FFD700;
    margin-bottom: 8px;
}

.dice-area {
    display: flex;
    gap: 10px;
    justify-content: center;
    margin-bottom: 8px;
}

.dice {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, #fff, #ddd);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: bold;
    color: #333;
    box-shadow: 2px 2px 5px rgba(0,0,0,0.3);
}

.dice.rolling {
    animation: diceRoll 0.5s ease-in-out;
}

@keyframes diceRoll {
    0%, 100% { transform: rotate(0deg); }
    25% { transform: rotate(15deg); }
    75% { transform: rotate(-15deg); }
}

