.center-info {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    width: 280px;
    height: 280px;
    background: radial-gradient(ellipse at center,
        #4a7c59 0%,
        #3d6848 30%,
        #2d5a3d 60%,
        #1f4d2e 100%);
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    box-shadow:
        0 0 0 8px #8b4513,
        0 0 0 12px #654321,
        0 0 0 16px #4a3520,
        0 0 30px rgba(0, 0, 0, 0.8),
        inset 0 0 60px rgba(0, 0, 0, 0.4);
    position: relative;
    overflow: hidden;
}

/* 麻将桌纹理装饰 */
.center-info::before {
    content: '';
    position: absolute;
    width: 240px;
    height: 240px;
    border: 3px solid rgba(255, 215, 0, 0.3);
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.center-info::after {
    content: '';
    position: absolute;
    width: 200px;
    height: 200px;
    border: 2px solid rgba(255, 215, 0, 0.2);
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

